item.command:
/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: TopModule.sv
@@
-        else
-            q <= {q[5], q[4:0]};
+        else
+            q <= {q[4:0], q[5]};
*** End Patch
PATCH

cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  wire data;
  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data));

  always #5 clk = ~clk;

  integer i;
  initial begin
    "'$display("time rst_n data q");
    $monitor("%0t %b %b %b", $time, rst_n, data, dut.q);
    #2 rst_n = 0;
    #8 rst_n = 1;
    for (i = 0; i < 8; i = i + 1) begin
      @(posedge clk);
      #1 $display("sample[%0d]=%b", i, data);
    end
    $finish;
  end
endmodule
EOF

iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

